// handleAdminListMirrors is GET /api/admin/mirrors. Returns every
// mirror placement across all jurisdictions, joined with github_repos
// for the upstream coords and with clusters for the jurisdiction.
//
// Foreign rows carry `foreign: true` and a `console_url` deep link so
// the admin SPA can surface them read-only — operators want a complete
// inventory, even though the per-cluster inspection RPCs are region-
// local (cluster.InternalURL is private DNS reachable only inside the
// jurisdiction's VPC). Action buttons on foreign rows are suppressed
// in the UI.
//
// Global mode doesn't register the route (registerGlobalRoutes
// skips registerControlPlaneRoutes), so the empty-jurisdiction
// case below is misconfiguration of a standalone/regional core.
func (s *Server) handleAdminListMirrors(w http.ResponseWriter, r *http.Request) {
	if !s.requirePlatformAdmin(w, r) {
		return
	}
	if s.mirrorRepos == nil {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "mirror service not configured"})
		return
	}
	if s.jurisdiction == "" {
		writeErr(w, r, http.StatusInternalServerError, errors.New("empty jurisdiction: refusing to list mirrors on a non-global core"))
		return
	}
	// Empty jurisdiction filter → every placement across every jurisdiction.
	// mirror_repos lives in global cockroach (see cmd/entire-core/cli/
	// migrate.go), so this is a read-only global query.
	p := ParseListParams(r, mirrorsSorts)
	page, err := s.mirrorRepos.ListPage(r.Context(), "", mirrorrepo.ListQuery{
		Search:  p.Q,
		OrderBy: p.OrderClause(mirrorsSorts, "repo"),
		Limit:   p.Limit,
		Offset:  p.Offset,
	})
	if err != nil {
		writeErr(w, r, http.StatusInternalServerError, err)
		return
	}
	out := make([]map[string]any, 0, len(page.Items))
	for _, row := range page.Items {
		out = append(out, s.mirrorRowJSON(row))
	}
