// TestCreate_ReturnsSuspendedAtOnRecreate verifies the idempotent re-create
// path surfaces an existing placement's admin suspension: a fresh insert has
// SuspendedAt == nil, and once the row is suspended a re-create returns
// created=false with SuspendedAt populated so the CLI can warn the operator.
func TestCreate_ReturnsSuspendedAtOnRecreate(t *testing.T) {
	t.Parallel()
	pool := newPool(t)
	svc := mirrorrepo.NewService(pool, &recordingAuthz{})
	ctx := context.Background()

	owner := "recreate-suspended-" + t.Name()
	clusterSlug := "test-cluster-" + t.Name()
	url := mirrorrepo.MirrorURL(owner, "r")

	githubRepoID := uniqueID()
	instID := uniqueID()
	if _, err := pool.Exec(ctx,
		`INSERT INTO github_installations (installation_id, account_id, account_login, account_type)
		 VALUES ($1, $2, $3, 'Organization')`,
		instID, uniqueID(), owner); err != nil {
		t.Fatalf("seed github_installations: %v", err)
	}
	if _, err := pool.Exec(ctx,
		`INSERT INTO github_repos (github_repo_id, owner_login, repo_name, is_private, default_branch, installation_id)
		 VALUES ($1, $2, 'r', true, 'main', $3)`,
		githubRepoID, owner, instID); err != nil {
		t.Fatalf("seed github_repos: %v", err)
	}

	// Fresh insert: created, never suspended.
	fresh, created, err := svc.Create(ctx, githubRepoID, clusterSlug, url)
	if err != nil {
		t.Fatalf("Create (fresh): %v", err)
	}
	if !created {
		t.Fatalf("expected created=true for a fresh mirror")
	}
	if fresh.SuspendedAt != nil {
		t.Fatalf("fresh Create SuspendedAt = %v, want nil", fresh.SuspendedAt)
	}

	// Re-create before suspension: found, still not suspended.
	if again, created, err := svc.Create(ctx, githubRepoID, clusterSlug, url); err != nil {
		t.Fatalf("Create (re-create): %v", err)
	} else if created {
		t.Fatalf("expected created=false on re-create")
	} else if again.SuspendedAt != nil {
		t.Fatalf("re-create SuspendedAt (pre-suspension) = %v, want nil", again.SuspendedAt)
	}

	// Suspend, then re-create: found and now flagged suspended.
	if err := svc.MarkSuspended(ctx, fresh.ID, time.Now()); err != nil {
		t.Fatalf("MarkSuspended: %v", err)
	}
	suspended, created, err := svc.Create(ctx, githubRepoID, clusterSlug, url)
	if err != nil {
		t.Fatalf("Create (post-suspension): %v", err)
	}
	if created {
		t.Fatalf("expected created=false on re-create of suspended mirror")
	}
	if suspended.SuspendedAt == nil {
		t.Fatalf("re-create SuspendedAt (post-suspension) = nil, want non-nil")
	}
}

